from __future__ import annotations

import base64
import gzip
import json
import os
import shutil
import subprocess
import sys
import traceback
from datetime import datetime
from pathlib import Path

PROJECT = Path(os.environ.get("PHOCAP_PROJECT", r"C:\PhoCap")).resolve()
APP = PROJECT / "app"
USERS = APP / "routers" / "users.py"
LIST_TPL = APP / "templates" / "users" / "list.html"

PAYLOAD = {'app/routers/users.py': '', 'app/templates/users/list.html': '', 'app/templates/users/bulk_level_all_preview.html': ''}

STAMP = datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP = PROJECT / "exports" / f"backup_bai_13b_6_v1_5_3_{STAMP}"
MANIFEST = BACKUP / "manifest.json"


def read(path: Path) -> str:
    if not path.exists():
        raise RuntimeError(f"Không tìm thấy: {path}")
    return path.read_text(encoding="utf-8-sig")


def preflight() -> None:
    users = read(USERS)
    tpl = read(LIST_TPL)

    # Chỉ yêu cầu đúng nền đã tách MN/TH/THCS; không khóa bằng hash.
    required = [
        "BAI_13B_6_V1_4_TAI_KHOAN_TRUONG_THEO_CAP",
        "SCHOOL_ACCOUNT_LEVEL_LABELS",
        "school_level",
    ]
    for marker in required:
        if marker not in users:
            raise RuntimeError(
                f"Source hiện tại chưa đúng nền tách tài khoản theo cấp: thiếu {marker}"
            )

    if "cap_hoc" not in tpl:
        raise RuntimeError("Template hiện tại chưa có cap_hoc. Dừng an toàn.")


def backup_files() -> list[dict]:
    BACKUP.mkdir(parents=True, exist_ok=False)
    items = []

    for rel in PAYLOAD:
        src = PROJECT / rel
        existed = src.exists()
        items.append({"path": rel, "existed": existed})
        if existed:
            dst = BACKUP / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

    MANIFEST.write_text(
        json.dumps(items, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return items


def restore_files(items: list[dict]) -> None:
    for item in reversed(items):
        target = PROJECT / item["path"]
        if item["existed"]:
            src = BACKUP / item["path"]
            if src.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, target)
        elif target.exists():
            target.unlink()


def write_payload() -> None:
    for rel, encoded in PAYLOAD.items():
        target = PROJECT / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(gzip.decompress(base64.b64decode(encoded)))


def verify() -> None:
    subprocess.run(
        [sys.executable, "-m", "py_compile", str(USERS)],
        cwd=PROJECT,
        check=True,
    )

    from jinja2 import Environment, FileSystemLoader
    env = Environment(loader=FileSystemLoader(str(APP / "templates")))
    env.get_template("users/list.html")
    env.get_template("users/bulk_level_all_preview.html")

    users = read(USERS)
    tpl = read(LIST_TPL)

    for marker in [
        "BAI_13B_6_V1_5_CAP_TAT_CA_TAI_KHOAN_THEO_CAP",
        '@router.get("/cap-tat-ca-theo-cap"',
        '@router.post("/cap-tat-ca-theo-cap"',
    ]:
        if marker not in users:
            raise RuntimeError(f"users.py thiếu {marker}")

    for marker in [
        "BAI_13B_6_V1_5_2_NUT_CAP_TAT_CA",
        "CẤP TÀI KHOẢN TOÀN CẤP",
        "Tạo tài khoản cho tất cả",
        "/tai-khoan/cap-tat-ca-theo-cap?cap=",
    ]:
        if marker not in tpl:
            raise RuntimeError(f"users/list.html thiếu {marker}")


def clear_cache() -> None:
    for cache in APP.rglob("__pycache__"):
        if cache.is_dir():
            shutil.rmtree(cache, ignore_errors=True)


def main() -> int:
    print("=" * 98)
    print("BÀI 13B-6 V1.5.3 - SỬA KIỂM TRA NÚT TẠO TÀI KHOẢN CHO TẤT CẢ")
    print("=" * 98)
    print("")
    print("Kết quả kiểm tra trước đó cho thấy source hoàn toàn CHƯA có code V1.5/V1.5.1.")
    print("Bản này không dựa vào V1.5/V1.5.1 nữa.")
    print("Nó ghi trực tiếp 3 tệp đã hoàn thiện lên đúng nền tách MN/TH/THCS hiện tại.")
    print("")
    print("Sau cài, tại TK trường MN / Tiểu học / THCS sẽ có:")
    print("  CẤP TÀI KHOẢN TOÀN CẤP")
    print("  [ Tạo tài khoản cho tất cả ]")
    print("")
    print("Nút chỉ mở màn hình xem trước; chưa tạo ngay.")
    print("Backend vẫn kiểm tra quyền Quản trị hệ thống.")
    print("Tài khoản đã có không bị tạo lại hoặc đổi mật khẩu.")
    print("")

    preflight()
    items = backup_files()

    try:
        write_payload()
        verify()
        clear_cache()

        print("")
        print("CAI DAT BAI 13B-6 V1.5.3 CAP TAT CA TAI KHOAN THANH CONG")
        print("Backup:", BACKUP)
        return 0

    except Exception:
        traceback.print_exc()
        print("")
        print("CÓ LỖI - ĐANG KHÔI PHỤC...")
        restore_files(items)
        print("ĐÃ KHÔI PHỤC VỀ TRƯỚC V1.5.3.")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
